import {
  Boxes,
  Database,
  FlaskConical,
  FolderKanban,
  Info,
  Laptop,
  Link2,
  Monitor,
  Moon,
  Settings2,
  Sun
} from "lucide-react";
import { NavLink, useParams } from "react-router-dom";

import {
  useTheme,
  type ThemePreference
